import java.util.*;

class Solution {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        k = k % n;                 // rotating n times changes nothing
        reverse(nums, 0, n - 1);   // whole array
        reverse(nums, 0, k - 1);   // first k elements
        reverse(nums, k, n - 1);   // the rest
    }

    private void reverse(int[] a, int i, int j) {
        while (i < j) {
            int t = a[i];
            a[i] = a[j];
            a[j] = t;
            i++;
            j--;
        }
    }
}

