function rotate(nums, k) {
  const n = nums.length; k %= n;
  const rev = (a, b) => { while (a < b) { const t = nums[a]; nums[a] = nums[b]; nums[b] = t; a++; b--; } };
  rev(0, n - 1); rev(0, k - 1); rev(k, n - 1);
}
